const tabId = 118779795;
const categoryInfo = await browserjs(tabId, () => {
  // Let's find any element that lists subtopics or categories
  // Often there are subcategories like Quantum Physics, General Physics, Condensed Matter, etc.
  const allLinks = Array.from(document.querySelectorAll('a'));
  const categoryLinks = allLinks.filter(a => {
    const href = a.getAttribute('href') || '';
    return href.includes('quantum') || href.includes('physics-news');
  }).map(a => ({ text: a.innerText.trim(), href: a.getAttribute('href') }));

  // Also search for any element containing "Quantum Physics"
  const elements = Array.from(document.querySelectorAll('*')).filter(el => {
    return el.children.length === 0 && el.textContent.includes('Quantum');
  }).map(el => ({ tag: el.tagName, text: el.textContent.trim(), parent: el.parentElement?.tagName, parentClass: el.parentElement?.className }));

  return { categoryLinks, elements };
});
console.log(JSON.stringify(categoryInfo, null, 2));

