  const parser = new DOMParser();
  const doc = parser.parseFromString(text, 'text/html');
  const items = Array.from(doc.querySelectorAll('article.sorted-article')).slice(0, 5);
  return items.map(art => {
    const titleLink = art.querySelector('h3 a, .news-link');
    return titleLink ? titleLink.textContent.trim() : '';
  });
});
